import React, { Component, Fragment } from 'react';
import axios from 'axios';
import moment from 'moment';
import { stringify } from 'qs';
import { toast } from 'react-toastify';
import BootstrapTable from 'react-bootstrap-table-next';
import paginationFactory from 'react-bootstrap-table2-paginator';
import ToolkitProvider, { Search } from 'react-bootstrap-table2-toolkit';
import Select from 'react-select';

import { axiosError, noDataIndication, resolveClientUrl } from '../../../common-functions';
import getResource from '../../../resourceHelper';
import Multiselect from '../../../shared/components/react-multiselect/index';
import ConfirmationModal from '../../../shared/components/ConfirmationModal';
import { PaginationOptions, PAStatus, PerformanceProcess, TextCenterCssClass, PostRequestHeaders } from '../../../constants';
import Edit from './Edit';

export default class Table extends Component {
    constructor(props) {
        super(props);

        this.state = {
            showCreateModal: false,
            showDeleteModal: false,
            addFilter: {
                groups: [],
                employee: null
            },
            showEditModal: false,
            showConfirmationModal: false,
            selectedSettingToUpdateStatus: null
        };
    }

    selectedIds = [];

    columns = [
        {
            dataField: 'rowNum',
            isDummyField: true,
            text: `${getResource('SymbolCount')}`,
            classes: TextCenterCssClass,
            headerStyle: { width: '50px' },
            formatter: (_cell, _row, rowIndex) => rowIndex + 1
        },
        {
            dataField: 'employee.groupName',
            text: `${getResource('Team')}`
        },
        {
            dataField: 'nickName',
            text: `${getResource('Employee')}`,
            formatter: (_cell, row) => `${row.employee.nickName} (${row.employee.fullName})`
        },
        {
            dataField: 'evaluator',
            text: `${getResource('Evaluator')}`,
            isDummyField: true,
            formatter: (_cell, row) => {
                const evaluatorProcess = row.processes.find(p => p.processId === PerformanceProcess.Evaluator);

                return (
                    <div>{evaluatorProcess.evaluator.nickName}</div>
                );
            }
        },
        {
            dataField: 'reviewer',
            text: `${getResource('Reviewer')}`,
            isDummyField: true,
            formatter: (_cell, row) => {
                const reviewerProcess = row.processes.find(p => p.processId === PerformanceProcess.Reviewer);

                return (
                    <Fragment>
                        <div>{reviewerProcess.evaluator.nickName}</div>
                        <div>
                            {reviewerProcess.startDate && moment(reviewerProcess.startDate).format('DD MMM, YYYY')}
                            {reviewerProcess.endDate && ` - ${moment(reviewerProcess.endDate).format('DD MMM, YYYY')}`}
                        </div>
                        <div>{reviewerProcess.status}</div>
                    </Fragment>
                );
            }
        },
        {
            dataField: 'status',
            text: `${getResource('PAStatus')}`,
            classes: TextCenterCssClass
        },
        {
            dataField: 'statusId',
            text: `${getResource('Include')}`,
            classes: TextCenterCssClass,
            headerStyle: { width: '80px' },
            formatter: (_cell, row, rowIndex) => {
                return (
                    <div className="checkbox">
                        <input type="checkbox" className="checkbox-custom" id={'chb-include' + rowIndex}
                            checked={row.statusId !== PAStatus.Rejected} onChange={() => this.editSettingStatusConfirmation(row)}
                        />
                        <label htmlFor={'chb-include' + rowIndex} />
                    </div>
                );
            }
        },
        {
            dataField: '',
            text: `${getResource('Action')}`,
            classes: TextCenterCssClass,
            headerStyle: { width: '80px' },
            isDummyField: true,
            formatter: (_cell, row) => {
                return (
                    <div className="action">
                        <a className="fa fa-pencil-square-o" title="Edit" onClick={() => this.editSetting(row.paRecordId)} />
                    </div>
                );
            }
        }];

    onEmployeeChange = employee => {
        this.setState({
            addFilter: {
                ...this.state.addFilter, employee: employee
            }
        });
    };

    onGroupsChange = groups => {
        this.setState({
            addFilter: { ...this.state.addFilter, groups: groups }
        });
    };

    addEmployeeSettings = () => {
        const { groups, employee } = this.state.addFilter;

        const groupIds = groups.length > 0 ? groups.map(e => e.id).toString() : null;
        const employeeId = employee ? employee.value : null;

        if (groupIds === null && employeeId === null) {
            toast.error('No team/employee selected');
            return;
        }

        axios({
            url: resolveClientUrl('Period/CreateEmployeeSettings'),
            method: 'post',
            data: stringify({
                __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,
                periodId: this.props.periodId,
                groupIds: groupIds,
                employeeId: employeeId
            }),
            headers: PostRequestHeaders
        }).then(response => {
            const data = response.data;

            if (data.isSuccessful) {
                toast.success(getResource('UpdatedSuccessfully'));
                this.props.refreshData();
            } else {
                toast.error(data.message);
            }
        }).catch(axiosError);
    };

    onSelectRow = (row, isSelect) => {
        if (isSelect) {
            this.selectedIds.push(row.paRecordId);
        } else {
            this.selectedIds = this.selectedIds.filter(e => e !== row.paRecordId);
        }
    };

    onSelectAllRows = isSelect => {
        if (isSelect) {
            this.selectedIds = this.props.data.map(e => e.paRecordId);
        } else {
            this.selectedIds = [];
        }
    };

    editSetting = paRecordId => {
        this.setState({ showEditModal: true, selectedIds: [paRecordId] });
    };

    editSettings = () => {
        if (this.selectedIds && this.selectedIds.length > 0) {
            this.setState({ showEditModal: true, selectedIds: this.selectedIds });
        } else {
            toast.error('No employee selected');
        }
    };

    generatePA = () => {
        if (this.selectedIds && this.selectedIds.length > 0) {
            axios({
                url: resolveClientUrl('Period/GeneratePA'),
                method: 'post',
                data: stringify({
                    __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,
                    periodId: this.props.periodId,
                    paRecordIds: this.selectedIds.toString()
                }),
                headers: PostRequestHeaders
            }).then(response => {
                const data = response.data;

                if (data.isSuccessful) {
                    toast.success('Generate Successfully');
                    this.setState({ showConfirmationModal: false });
                    this.props.refreshData();
                } else {
                    toast.error(data.message);
                }
            }).catch(axiosError);
        } else {
            toast.error('No employee selected');
        }
    };

    onEditSettingStatus = () => {
        axios({
            url: resolveClientUrl('Period/EditEmployeeSettingStatus'),
            method: 'post',
            data: stringify({
                __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,
                paRecordId: this.state.selectedSettingToUpdateStatus.paRecordId,
                isExcluded: this.state.selectedSettingToUpdateStatus.statusId !== PAStatus.Rejected
            }),
            headers: PostRequestHeaders
        }).then(response => {
            const data = response.data;

            if (data.isSuccessful) {
                toast.success(getResource('UpdatedSuccessfully'));
                this.setState({ showConfirmationModal: false });
                this.props.getSetting(this.state.selectedSettingToUpdateStatus.paRecordId);
            } else {
                toast.error(data.message);
            }
        }).catch(axiosError);
    };

    closeEditModal = () => this.setState({ showEditModal: false });

    editSettingStatusConfirmation = setting => this.setState({ showConfirmationModal: true, selectedSettingToUpdateStatus: setting });

    onEditSuccess = () => {
        this.setState({ showEditModal: false });
        this.props.refreshData();
    };

    closeConfirmationModal = () => this.setState({ showConfirmationModal: false });

    render() {
        const { periodId, data, groups, employeeOptions } = this.props;
        const groupOptions = groups.map(item => {
            return {
                id: item.value,
                text: item.label,
                checked: this.state.addFilter.groups.findIndex(x => x.id === item.value) > -1
            };
        });

        return (
            <Fragment>
                <ToolkitProvider keyField="paRecordId" columns={this.columns} data={data} search={{ searchFormatted: true }} >
                    {
                        props => {
                            return (
                                <Fragment>
                                    <div className="search-wrapper clearfix" >
                                        <div className="pull-left field-group">
                                            <label>{getResource('Team')}</label>
                                            <div className="control-content">
                                                <Multiselect hasSearchBox
                                                    items={groupOptions}
                                                    onChange={this.onGroupsChange}
                                                />
                                            </div>
                                        </div>
                                        <div className="pull-left field-group">
                                            <label>{getResource('Employee')}</label>
                                            <div className="control-content">
                                                <Select className="react-select-container" classNamePrefix="react-select"
                                                    value={this.state.addFilter.employee} name="employee" isClearable
                                                    options={employeeOptions} onChange={this.onEmployeeChange}
                                                />
                                            </div>
                                        </div>
                                        <div className="pull-left field-group">
                                            <button className="btn btn-primary" onClick={this.addEmployeeSettings}>{getResource('Add')}</button>
                                        </div>
                                        <div className="search pull-right">
                                            <Search.SearchBar {...props.searchProps} placeholder="" delay={100} className="search-textbox" />
                                            <span className="fa fa-search icon" />
                                        </div>
                                    </div>
                                    <div className="search-wrapper clearfix" >
                                        <div className="pull-left btn-block">
                                            <button className="btn btn-primary" onClick={this.editSettings}>
                                                {getResource('EditEmployeeSetting')}
                                            </button>
                                            <button className="btn btn-primary" onClick={this.generatePA}>
                                                {getResource('GeneratePA')}
                                            </button>
                                        </div>
                                    </div>
                                    <BootstrapTable  {...props.baseProps} noDataIndication={noDataIndication}
                                        pagination={paginationFactory(PaginationOptions)} striped
                                        classes="table-employee-settings"
                                        selectRow={{
                                            mode: 'checkbox', onSelect: this.onSelectRow, onSelectAll: this.onSelectAllRows, selectionRenderer: ({ mode, ...rest }) => (
                                                <div className="checkbox">
                                                    <input type={mode} {...rest} className="checkbox-custom" />
                                                    <label />
                                                </div>
                                            ),
                                            selectionHeaderRenderer: ({ indeterminate, mode, checked }) => (
                                                <div className="checkbox">
                                                    <input type={mode} className="checkbox-custom"
                                                        ref={input => {
                                                            if (input) {
                                                                input.indeterminate = indeterminate;
                                                            }
                                                        }}
                                                        checked={checked}
                                                    />
                                                    <label />
                                                </div>
                                            )
                                        }}
                                    />
                                </Fragment>
                            );
                        }
                    }
                </ToolkitProvider>
                {
                    this.state.showEditModal &&
                    <Edit showModal={this.state.showEditModal}
                        closeModal={this.closeEditModal}
                        paRecordIds={this.state.selectedIds}
                        periodId={periodId}
                        settings={data.filter(e => this.state.selectedIds.some(s => s === e.paRecordId))}
                        employeeOptions={employeeOptions}
                        onEditSuccess={this.onEditSuccess}
                    />
                }
                {
                    this.state.showConfirmationModal &&
                    <ConfirmationModal
                        showModal={this.state.showConfirmationModal}
                        action={this.state.selectedSettingToUpdateStatus.statusId === PAStatus.Rejected ? 'include' : 'exclude'}
                        name={this.state.selectedSettingToUpdateStatus.nickName}
                        onCloseModal={this.closeConfirmationModal}
                        onSubmit={this.onEditSettingStatus}
                    />
                }
            </Fragment>
        );
    }
}